values ('dialog_fq_merid_089', 'fq_merid_089', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Come in. Business has been good — but it could be better. The World Engine is the most valuable asset in Xylos history", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cartel doesn''t deal in ideology — we deal in opportunity. Every monster cleared is a trade route secured. Every route secured is profit. Simple arithmetic.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Market for a World: Unclaimed Ground 05. In Eternal Gate: Defeat 1 ABYSS_HARBINGER. The contract pays for a verified result. Keep the route in mind; that''s where the real value sits.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 514)
