values ('dialog_fq_merid_091', 'fq_merid_091', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Ah, Associate. I was just reviewing the ledgers. The Engine flushes remaining hostile assets", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions fight over principles. Principles don''t pay for ship repairs. The Cartel pays in hard currency — always has, always will.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Market for a World: Witness at the Ridge 05. In Eternal Gate: Defeat 1 ABYSS_HARBINGER. The contract pays for a verified result. Keep the route in mind; that''s where the real value sits.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 516)
