insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_omni_003', 'fq_omni_003', 'npc_omnicorp_class_trainer', 'greeting', '[{"id": "greeting", "text": "Asset, your metrics have been reviewed. Calibration by Elimination — The Plateau Drones were OmniCorp''s own early-model survey units, deployed o...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "OmniCorp doesn''t waste resources on sentiment. Every operation is calculated for maximum return. This one is flagged high-yield — your compensation reflects that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Asset Survey: Ashes on the Route 01. In Highland Plateau: Defeat 3 PLATEAU_HARE. Record the deliverable and any deviation from projection. Close the operation cleanly.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 528)
