values ('dialog_fq_omni_056', 'fq_omni_056', 'npc_omnicorp_class_trainer', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. Gigantic Jotunns function as organic servers hosting hostile processes", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Grid Security: No Safe Shortcut 03. In Aethel Storm Ridge: Defeat 8 CHRONO_WRAITH. Record the deliverable and any deviation from projection. Close the operation cleanly.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 580)
