values ('dialog_fq_omni_057', 'fq_omni_057', 'npc_omnicorp_class_trainer', 'greeting', '[{"id": "greeting", "text": "Asset, your metrics have been reviewed. Tyrant Hardware Removal — Crystal Tyrants are foreign hardware installations in the Heart sector", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "OmniCorp doesn''t waste resources on sentiment. Every operation is calculated for maximum return. This one is flagged high-yield — your compensation reflects that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Grid Security: Aethel Aftershock 03. In Aethel Storm Ridge: Defeat 8 CHRONO_WRAITH. Record the deliverable and any deviation from projection. Close the operation cleanly.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 581)
