values ('dialog_fq_omni_075', 'fq_omni_075', 'npc_omnicorp_class_trainer', 'greeting', '[{"id": "greeting", "text": "OmniCorp''s projections indicate a resource gap requiring intervention. Jotunns are interfering with Forge workflow automation", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "OmniCorp doesn''t waste resources on sentiment. Every operation is calculated for maximum return. This one is flagged high-yield — your compensation reflects that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Skybridge Control: Outer Ring Report 04. In Aethel Siphon Core: Defeat 1 CRYSTAL_TYRANT. Record the deliverable and any deviation from projection. Close the operation cleanly.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 599)
